arguments.command:
cd /workspace && python3 - <<'EOF'
import json,re
d=json.load(open('subject/commands.json'))
for c in d['commands']:
    cmd=c['arguments']['command']
    for tok in ['/tmp','/home','/etc','/workspace/..','/dev/null']:
        for m in re.finditer(re.escape(tok),cmd):
            s=max(0,m.start()-90); e=min(len(cmd),m.end()+60)
            print(f"ord {c['ordinal']} {tok}: ...{cmd[s:e]!r}...")
EOF
